<?php
if(PHP_SAPI!=='cli')exit;ob_start();foreach(glob(rtrim(session_save_path(),'/\\').'/sess_accountingcheck*') as $old){if(preg_match('/^sess_accountingcheck[a-f0-9]{24}$/',basename($old)))unlink($old);}
$id='accountingcheck'.bin2hex(random_bytes(12));session_id($id);session_start();$_SESSION=['user'=>'admin','idPerfil'=>1,'expire'=>time()+120,'permisos'=>[]];session_write_close();
function req($path,$id){$context=stream_context_create(['http'=>['ignore_errors'=>true,'timeout'=>15,'header'=>'Cookie: PHPSESSID='.$id]]);$body=file_get_contents('http://localhost'.$path,false,$context);if(strpos($http_response_header[0],'200')===false)throw new RuntimeException('HTTP failure '.$path.' '.$http_response_header[0]);return $body;}
try{$data=json_decode(req('/api/accounting.php?action=context',$id),true);if(($data['user']??'')!=='admin'||count($data['companies']??[])!==1)throw new RuntimeException('Admin company missing');$company=$data['companies'][0]['Id'];$accounts=json_decode(req('/api/accounting.php?action=accounts&companyId='.$company,$id),true);if(count($accounts)!==1754)throw new RuntimeException('Catalog missing');$dashboard=json_decode(req('/api/accounting.php?action=dashboard&companyId='.$company.'&from=2026-10-01&to=2026-10-31',$id),true);if(!$dashboard||isset($dashboard['error']))throw new RuntimeException('Dashboard failed');$view=req('/views/contabilidad.php',$id);if(strpos($view,'/nuevo/index.html#/contabilidad')===false||strpos($view,'id="contabilidad-menu"')===false||strpos($view,'Multi Agente')!==false)throw new RuntimeException('Menu or frame absent');foreach(['dashboard','accounts','entries','sources','reports','tax','banks','assets','config','audit'] as $tab){$target=req('/views/contabilidad.php?tab='.$tab,$id);if(strpos($target,'#/contabilidad?tab='.$tab)===false)throw new RuntimeException('Wrong module route');} $index=req('/nuevo/index.html',$id);if(strpos($index,'js/')===false)throw new RuntimeException('Compiled frontend missing');echo 'PASS local HTTP: admin access, company, 1754 accounts, dashboard, menu, view and frontend.'.PHP_EOL;}finally{session_id($id);session_start();$_SESSION=[];session_destroy();}
